from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)

        # first_index[v] = smallest index in elements whose value is v,
        # or -1 if value v does not exist.
        first_index = [-1] * (max_group + 1)

        for idx, value in enumerate(elements):
            if value <= max_group and first_index[value] == -1:
                first_index[value] = idx

        # best_for_value[g] = smallest element index that can divide g.
        best_for_value = [-1] * (max_group + 1)

        for value in range(1, max_group + 1):
            idx = first_index[value]
            if idx == -1:
                continue

            for multiple in range(value, max_group + 1, value):
                if best_for_value[multiple] == -1 or idx < best_for_value[multiple]:
                    best_for_value[multiple] = idx

        return [best_for_value[group] for group in groups]
