from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers

        def sort_key(event: List[str]):
            event_type, timestamp, _ = event
            # OFFLINE events must be processed before MESSAGE events at the same timestamp.
            return (int(timestamp), 0 if event_type == "OFFLINE" else 1)

        for event_type, timestamp, data in sorted(events, key=sort_key):
            current_time = int(timestamp)

            if event_type == "OFFLINE":
                user_id = int(data)
                offline_until[user_id] = current_time + 60
            else:
                for token in data.split():
                    if token == "ALL":
                        for user in range(numberOfUsers):
                            mentions[user] += 1
                    elif token == "HERE":
                        for user in range(numberOfUsers):
                            if offline_until[user] <= current_time:
                                mentions[user] += 1
                    else:
                        user_id = int(token[2:])
                        mentions[user_id] += 1

        return mentions
