class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def get_substrings(x: str):
            subs = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    subs.append(x[i:j])
            return subs

        s_substrings = get_substrings(s)
        t_substrings = get_substrings(t)

        ans = 0
        for left in s_substrings:
            left_len = len(left)
            for right in t_substrings:
                total_len = left_len + len(right)
                if total_len <= ans:
                    continue

                candidate = left + right
                if candidate == candidate[::-1]:
                    ans = total_len

        return ans
